    if(!newp)
      return CURLUE_OUT_OF_MEMORY;
    path_alloced = TRUE;
    strcpy_url(newp, path, TRUE); /* consider it relative */
    path = newp;
}

fragment = strchr(path, '#');
if(fragment)
    *fragment++ = 0;

query = strchr(path, '?');
if(query)
    *query++ = 0;

if(!path[0])
    path = NULL;
else if(!(flags & CURLU_PATH_AS_IS)) {
    char *newp = Curl_dedotdotify(path);
    if(!newp) {
      if(path_alloced)
        free(path);
      return CURLUE_OUT_OF_MEMORY;
    }

    if(strcmp(newp, path)) {
      if(path_alloced)
        free(path);   // <-- frees newp (the URL-encoded buffer)
      path = newp;
